<!DOCTYPE html>
<html lang="zh-CN">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>小龙坎 - 折叠栏</title>
    <style>
      * { margin: 0; padding: 0; box-sizing: border-box; }
      body { background: transparent; color: #8a8f98; font: 15px/1.7 system-ui, -apple-system, 'PingFang SC', 'Microsoft YaHei', sans-serif; }
      .cat-collapsible { border: 1px solid rgba(138, 143, 152, 0.4); border-radius: 6px; overflow: hidden; }
      .cat-header { padding: 8px 12px; cursor: pointer; user-select: none; }
      .cat-title { font-weight: 600; }
      .cat-content { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
      .cat-content-inner { padding: 0 12px 10px; overflow-wrap: anywhere; white-space: pre-wrap; }
      .cat-content-inner p { margin: 0 0 0.6em; }
      .cat-footer-toggle { padding: 4px 0 10px; text-align: center; font-size: 13px; opacity: 0.7; cursor: pointer; user-select: none; }
    </style>
